// Values a notebook commonly shows, formatted by util.inspect (Node) and
// Deno.inspect (Deno) with the kernel's settings, colors off.
export const cases = {
  string: "hello",
  "string with quotes": `it's "x"`,
  number: 42,
  bigint: 10n,
  "array of numbers": [1, 2, 3],
  "long array": Array.from({ length: 120 }, (_, i) => i),
  "plain object": { a: 1, b: "two", c: [3] },
  "nested object": { a: { b: { c: { d: { e: 1 } } } } },
  Map: new Map([["k", 1], ["j", { x: 2 }]]),
  Set: new Set([1, "two"]),
  Date: new Date(0),
  RegExp: /ab+c/gi,
  Error: new TypeError("boom"),
  "class instance": new (class Point { constructor() { this.x = 1; this.y = 2; } })(),
  function: function add(a, b) { return a + b; },
  "arrow function": (x) => x,
  class: class Shape {},
  Symbol: Symbol("s"),
  null: null,
  Promise: Promise.resolve(1),
  "Uint8Array": new Uint8Array([1, 2, 3]),
  "object with symbol key": { [Symbol("k")]: 1 },
  "empty object": {},
  "empty array": [],
  "sparse array": [1, , 3],
  "array with props": Object.assign([1], { extra: true }),
  "object with getter": { get g() { return 1; } },
  "null-prototype object": Object.assign(Object.create(null), { a: 1 }),
  "long string in object": { s: "x".repeat(100) },
  "multiline string": "line one\nline two",
};
